&reftitle.description;
public voidYaf_Plugin_Abstract::routerShutdown Yaf_Request_Abstractrequest Yaf_Response_Abstractresponse
Este gancho é acionado após o término do processo de roteamento e a resolução dos nomes do controlador e da ação, mas antes do início do laço de despacho. Geralmente é usado para verificações de controle de acesso, como uma verificação de login, pois o controlador e a ação de destino já são conhecidos.

  &reftitle.examples;

   Exemplo de Yaf_Plugin_Abstract::routerShutdown


<?php
class AuthPlugin extends Yaf_Plugin_Abstract
{
    public function routerShutdown(Yaf_Request_Abstract $request, Yaf_Response_Abstract $response)
    {
        /* o roteamento terminou, portanto o controlador e a ação de destino são
         * conhecidos: verifica se o usuário pode acessá-los */
        $public = array("Index" => array("index"), "User" => array("login"));

        $controller = $request->getControllerName();
        $action = $request->getActionName();

        if (isset($public[$controller]) && in_array($action, $public[$controller])) {
            return;
        }

        if (!Yaf_Session::getInstance()->has("login")) {
            $response->setRedirect("/user/login");
            $request->setDispatched(true); // não despacha a requisição
        }
    }
}

/* os plugins são registrados no bootstrap */
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initPlugin(Yaf_Dispatcher $dispatcher)
    {
        $dispatcher->registerPlugin(new AuthPlugin());
    }
}
?>
